66	struct allwinner_usb {
67		struct usb_device *aw_dev;     /* init: probe_aw */
68		struct usb_interface *aw_intf;	//store interface to get endpoint
69		unsigned int ifnum;             /* Interface number of the USB device */
70		int isopen;                     /* nz if open */
71		int present;                    /* Device is present on the bus */
72		char *obuf, *ibuf;              /* transfer buffers */
73		size_t	bulk_in_size;			/* the size of the receive buffer */
74		unsigned char bulk_in_endpointAddr; /* Endpoint assignments */
75		unsigned char bulk_out_endpointAddr; /* Endpoint assignments */
76		wait_queue_head_t wait_q;       /* for timeouts */
77		struct mutex lock;          /* general race avoidance */
78	};
