121	static struct allwinner_usb aw_instance;
122	
123	static int open_aw(struct inode *inode, struct file *file)
124	{
125		struct allwinner_usb *aw = &aw_instance;
126		struct usb_interface* intf;// = aw->aw_intf; 
127		struct usb_host_interface *iface_desc;
128		struct usb_endpoint_descriptor *endpoint;
129		int subminor;
130		int i;
131	
132		if (aw->isopen || !aw->present) {
133			mutex_unlock(&(aw->lock));
134			return -EBUSY;
135		}
136	
137		subminor = iminor(inode);
138		intf = usb_find_interface(&aw_driver, subminor);;
139		if(intf == NULL)
140			return -ENODEV;
141	
142		iface_desc = intf->cur_altsetting;
143		aw->bulk_in_endpointAddr = 0;
144		aw->bulk_out_endpointAddr = 0;
145		for (i = 0; i < iface_desc->desc.bNumEndpoints; ++i) {
146			endpoint = &iface_desc->endpoint[i].desc;
147	
148			if ( !aw->bulk_in_endpointAddr && usb_endpoint_is_bulk_in(endpoint)) {
149				/* we found a bulk in endpoint */
150				aw->bulk_in_endpointAddr = endpoint->bEndpointAddress;
151				printk(KERN_DEBUG"bulk_in_endpointAddr = %d\n", endpoint->bEndpointAddress);
152			}
153	
154			if ( !aw->bulk_out_endpointAddr && usb_endpoint_is_bulk_out(endpoint)) {
155				/* we found a bulk out endpoint */
156				aw->bulk_out_endpointAddr = endpoint->bEndpointAddress;
157				printk(KERN_DEBUG"bulk_out_endpointAddr = %d\n", endpoint->bEndpointAddress);
158			}
159		}
160	
161		if (!(aw->bulk_in_endpointAddr && aw->bulk_out_endpointAddr)) {
162			printk(KERN_ERR"Could not find both bulk-in and bulk-out endpoints");
163			return -EPIPE;
164		}
165	
166		aw->isopen = 1;
167		init_waitqueue_head(&aw->wait_q);
168	
169		return 0;
170	}
171	
172	static int close_aw(struct inode *inode, struct file *file)
173	{
174		struct allwinner_usb *aw = &aw_instance;
175	
176		aw->isopen = 0;
177	
178		return 0;
179	}
