181	static long ioctl_aw(struct file *file, unsigned int cmd, unsigned long arg)
182	{
183		struct allwinner_usb *aw = &aw_instance;
184		int retval=0;
185		struct usb_param param_tmp;
186	
187		struct aw_command aw_cmd;
188		void __user *data;
189		int value = 0;
190		int buffer_len = 0;
191	
192		int result = 0;
193		int actual_len = 0;
194		unsigned int nPipe = 0;
195	
196		mutex_lock(&(aw->lock));
197		if (aw->present == 0 || aw->aw_dev == NULL) {
198			retval = -ENODEV;
199			goto err_out;
200		}
201	
202		param_tmp.test_num = 0;
203		param_tmp.p1 = 0;
204		param_tmp.p2 = 0;
205		param_tmp.p3 = 0;
206	
207	
208		switch (cmd) {
209			case AWUSB_IOCRESET:
210				printk(KERN_DEBUG"ioctl_aw--AWUSB_IOCRESET\n");
211				break;
212	
213			case AWUSB_IOCSET:    
214	
215				if (copy_from_user(&param_tmp, (void __user *)arg, sizeof(param_tmp)))
216					retval= -EFAULT;
217	
218				printk(KERN_DEBUG"param_tmp.test_num = %d\n", param_tmp.test_num);
219				printk(KERN_DEBUG"param_tmp.p1 = %d\n", param_tmp.p1);
220				printk(KERN_DEBUG"param_tmp.p2 = %d\n", param_tmp.p2);
221				printk(KERN_DEBUG"param_tmp.p3 = %d\n", param_tmp.p3);
222	
223				break;
224	
225			case AWUSB_IOCGET:
226	
227				param_tmp.test_num = 3;
228				param_tmp.p1 = 4;
229				param_tmp.p2 = 5;
230				param_tmp.p3 = 6;
231	
232				if (copy_to_user((void __user *)arg, &param_tmp, sizeof(param_tmp)))
233					retval= -EFAULT;
234	
235				break;
236	
237			case AWUSB_IOCSEND:
238	
239				data = (void __user *) arg;
240				if (data == NULL)
241					break;
242	
243				if (copy_from_user(&aw_cmd, data, sizeof(struct aw_command))) {
244					retval = -EFAULT;
245					goto err_out;
246				}
247	
248				buffer_len = aw_cmd.length;
249				value = aw_cmd.value;
250	
251				if (buffer_len > OBUF_SIZE) {
252					retval = - EINVAL;
253					goto err_out;
254				}
255	
256				// stage 1, get data from app
257				if (copy_from_user(aw->obuf, aw_cmd.buffer, aw_cmd.length)) {
258					retval = -EFAULT;
259					goto err_out;
260				}
261	
262				//stage 2, send data to usb device
263				nPipe = usb_sndbulkpipe(aw->aw_dev, aw->bulk_out_endpointAddr);
264				result = usb_bulk_msg(aw->aw_dev, nPipe,
265						aw->obuf, buffer_len, &actual_len, MAX_TIME_WAIT);  
266				if (result) {
267					printk(KERN_ERR"Write Whoops - %d", (int)result);
268					printk(KERN_ERR"send pipe - %u", nPipe);
269					retval = result;
270					goto err_out;
271				}
272	
273				break;
274	
275			case AWUSB_IOCRECV:
276	
277				data = (void __user *) arg;
278				if (data == NULL)
279					break;
280				if (copy_from_user(&aw_cmd,data, sizeof(struct aw_command))) {
281					retval = -EFAULT;
282					goto err_out;
283				}
284				if (aw_cmd.length < 0) {
285					retval = - EINVAL;
286					goto err_out;
287				}
288				buffer_len = aw_cmd.length;
289				value = aw_cmd.value;
290	
291				if (buffer_len > aw->bulk_in_size) {
292					retval = - EINVAL;
293					goto err_out;
294				}
295	
296				memset(aw->ibuf, 0x00, aw->bulk_in_size);
297	
298				// stage 1, get data from usb device
299				nPipe = usb_rcvbulkpipe(aw->aw_dev, aw->bulk_in_endpointAddr);
300				result = usb_bulk_msg(aw->aw_dev, nPipe,
301						aw->ibuf, buffer_len, &actual_len, MAX_TIME_WAIT);
302	
303				if (result) {
304					printk(KERN_ERR"Read Whoops - %d", result);
305					printk(KERN_ERR"Receive pipe - %u", nPipe);
306					retval = result;
307					goto err_out;
308				}
309	
310				// stage 2, copy data to app in user space
311				if (copy_to_user(aw_cmd.buffer, aw->ibuf, aw_cmd.length)) {
312					retval = - EFAULT;
313					goto err_out;
314				}
315				break;
316	
317			case AWUSB_IOCSEND_RECV:
318				printk(KERN_DEBUG"ioctl_aw--AWUSB_IOCSEND_RECV\n");
319	
320				break;
321	
322			default:
323				retval = -ENOTTY;
324				break;
325		}
326	
327	err_out:
328		mutex_unlock(&(aw->lock));
329		return retval;
330	
331	}
