333		static ssize_t
334	write_aw(struct file *file, const char __user *buffer,
335			size_t count, loff_t * ppos)
336	{
337		DEFINE_WAIT(wait);
338		struct allwinner_usb *aw = &aw_instance;
339	
340		unsigned long copy_size;
341		unsigned long bytes_written = 0;
342		unsigned int partial;
343	
344		int result = 0;
345		int maxretry;
346		int errn = 0;
347		int intr;
348	
349		intr = mutex_lock_interruptible(&(aw->lock));
350		if (intr)
351			return -EINTR;
352		/* Sanity check to make sure aw is connected, powered, etc */
353		if (aw->present == 0 || aw->aw_dev == NULL) {
354			mutex_unlock(&(aw->lock));
355			return -ENODEV;
356		}
357	
358	
359	
360		do {
361			unsigned long thistime;
362			char *obuf = aw->obuf;
363	
364			thistime = copy_size =
365				(count >= OBUF_SIZE) ? OBUF_SIZE : count;
366			if (copy_from_user(aw->obuf, buffer, copy_size)) {
367				errn = -EFAULT;
368				goto error;
369			}
370			maxretry = 5;
371			while (thistime) {
372				if (!aw->aw_dev) {
373					errn = -ENODEV;
374					goto error;
375				}
376				if (signal_pending(current)) {
377					mutex_unlock(&(aw->lock));
378					return bytes_written ? bytes_written : -EINTR;
379				}
380	
381				result = usb_bulk_msg(aw->aw_dev,
382						usb_sndbulkpipe(aw->aw_dev, aw->bulk_out_endpointAddr),
383						obuf, thistime, &partial, MAX_TIME_WAIT);
384	
385				printk(KERN_DEBUG"write stats: result:%d thistime:%lu partial:%u",
386						result, thistime, partial);
387	
388				if (result == -ETIMEDOUT) {	/* NAK - so hold for a while */
389					if (!maxretry--) {
390						errn = -ETIME;
391						goto error;
392					}
393					prepare_to_wait(&aw->wait_q, &wait, TASK_INTERRUPTIBLE);
394					schedule_timeout(NAK_TIMEOUT);
395					finish_wait(&aw->wait_q, &wait);
396					continue;
397				} else if (!result && partial) {
398					obuf += partial;
399					thistime -= partial;
400				} else
401					break;
402			};
403			if (result) {
404				printk(KERN_ERR"Write Whoops - %x", result);
405				errn = -EIO;
406				goto error;
407			}
408			bytes_written += copy_size;
409			count -= copy_size;
410			buffer += copy_size;
411		} while (count > 0);
412	
413		mutex_unlock(&(aw->lock));
414	
415		return bytes_written ? bytes_written : -EIO;
416	
417	error:
418		mutex_unlock(&(aw->lock));
419		return errn;
420	}
