422	static ssize_t
423	read_aw(struct file *file, char __user *buffer, size_t count, loff_t * ppos)
424	{
425		DEFINE_WAIT(wait);
426		struct allwinner_usb *aw = &aw_instance;
427		ssize_t read_count;
428		unsigned int partial;
429		int this_read;
430		int result;
431		int maxretry = 10;
432		char *ibuf;
433		int intr;
434	
435		intr = mutex_lock_interruptible(&(aw->lock));
436		if (intr)
437			return -EINTR;
438		/* Sanity check to make sure aw is connected, powered, etc */
439		if (aw->present == 0 || aw->aw_dev == NULL) {
440			mutex_unlock(&(aw->lock));
441			return -ENODEV;
442		}
443	
444		ibuf = aw->ibuf;
445	
446		read_count = 0;
447	
448	
449		while (count > 0) {
450			if (signal_pending(current)) {
451				mutex_unlock(&(aw->lock));
452				return read_count ? read_count : -EINTR;
453			}
454			if (!aw->aw_dev) {
455				mutex_unlock(&(aw->lock));
456				return -ENODEV;
457			}
458			this_read = (count >= aw->bulk_in_size) ? aw->bulk_in_size : count;
459	
460			result = usb_bulk_msg(aw->aw_dev,
461					usb_rcvbulkpipe(aw->aw_dev, aw->bulk_in_endpointAddr),
462					ibuf, this_read, &partial,
463					MAX_TIME_WAIT);
464	
465			printk(KERN_DEBUG"read stats: result:%d this_read:%u partial:%u",
466					result, this_read, partial);
467	
468			if (partial) {
469				count = this_read = partial;
470			} else if (result == -ETIMEDOUT || result == 15) {	/* FIXME: 15 ??? */
471				if (!maxretry--) {
472					mutex_unlock(&(aw->lock));
473					printk(KERN_ERR"read_aw: maxretry timeout");
474					return -ETIME;
475				}
476				prepare_to_wait(&aw->wait_q, &wait, TASK_INTERRUPTIBLE);
477				schedule_timeout(NAK_TIMEOUT);
478				finish_wait(&aw->wait_q, &wait);
479				continue;
480			} else if (result != -EREMOTEIO) {
481				mutex_unlock(&(aw->lock));
482				printk(KERN_ERR"Read Whoops - result:%u partial:%u this_read:%u",
483						result, partial, this_read);
484				return -EIO;
485			} else {
486				mutex_unlock(&(aw->lock));
487				return (0);
488			}
489	
490			if (this_read) {
491				if (copy_to_user(buffer, ibuf, this_read)) {
492					mutex_unlock(&(aw->lock));
493					return -EFAULT;
494				}
495				count -= this_read;
496				read_count += this_read;
497				buffer += this_read;
498			}
499		}
500		mutex_unlock(&(aw->lock));
501		return read_count;
502	}
