588	static void disconnect_aw(struct usb_interface *intf)
589	{
590		struct allwinner_usb *aw = usb_get_intfdata (intf);
591	
592		usb_set_intfdata (intf, NULL);
593		if (aw) {
594			usb_deregister_dev(intf, &usb_aw_class);
595	
596			mutex_lock(&(aw->lock));
597			if (aw->isopen) {
598				aw->isopen = 0;
599				/* better let it finish - the release will do whats needed */
600				aw->aw_dev = NULL;
601				mutex_unlock(&(aw->lock));
602				return;
603			}
604			kfree(aw->ibuf);
605			kfree(aw->obuf);
606	
607			dev_info(&intf->dev, "USB aw disconnected.\n");
608	
609			aw->present = 0;
610			mutex_unlock(&(aw->lock));
611		}
612	}
